import {useEffect,useState} from 'react';
import {Link,useSearchParams,useLocation} from 'react-router-dom';
import {useSupplierDirectory} from '@/hooks/useSupplierDirectory';
import {usePayables} from '@/hooks/usePayables';
import {useAuth} from '@/hooks/useAuth';
import {usePreviewMode} from '@/hooks/usePreviewMode';
import {supabase} from '@/integrations/supabase/client';
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription} from '@/components/ui/dialog';
import {Button} from '@/components/ui/button';
import {Input} from '@/components/ui/input';
import {Label} from '@/components/ui/label';
import {Textarea} from '@/components/ui/textarea';
import {formatMenuCurrency,formatCurrency,formatDate,formatPercent} from '@/utils/format';
import {hongKongDate,previousCalendarMonth,itemRanking,priceMoves} from '@/utils/purchasingOverview';
import {toast} from 'sonner';
export function SupplierNameLink({id,children}:{id:string|null|undefined;children:React.ReactNode}){const location=useLocation();if(!id)return <>{children}</>;const params=new URLSearchParams(location.search);params.set('supplierProfile',id);return <Link onClick={e=>e.stopPropagation()} className="hover:underline underline-offset-4" to={`${location.pathname}?${params}`}>{children}</Link>;}
export function SupplierProfileDialog(){const [params,setParams]=useSearchParams();const id=params.get('supplierProfile');return id?<Profile id={id} onClose={()=>{const next=new URLSearchParams(params);next.delete('supplierProfile');setParams(next,{replace:true});}}/>:null;}
function Profile({id,onClose}:{id:string;onClose:()=>void}){const data=useSupplierDirectory();const payables=usePayables();const {isAdmin}=useAuth();const {isPreviewActive}=usePreviewMode();const [editing,setEditing]=useState(false),[busy,setBusy]=useState(false);const [form,setForm]=useState({contact_person:'',email:'',phone:'',address:'',payment_terms:'',delivery_days:'',notes:''});
 const alias=data.data?.suppliers.find(s=>s.id===id);const row=data.data?.rows.find(s=>s.id===(alias?.directory_merged_into??id));useEffect(()=>{if(row)setForm({contact_person:row.contact_person??'',email:row.email??'',phone:row.phone??'',address:row.address??'',payment_terms:row.payment_terms??'',delivery_days:row.delivery_days.join(', '),notes:row.notes??''});},[row?.id]);
 const owed=row?payables.invoices.filter(i=>row.ids.has(i.supplier_id)).reduce((n,i)=>n+i.outstanding_amount,0)+(data.data?.bills??[]).filter(b=>row.ids.has(b.supplier_id)&&b.approval_status==='posted').reduce((n,b)=>n+Math.max(0,Number(b.total_amount)-Number(b.paid_amount)),0):0;
 const month=row?.lastInvoice?.slice(0,7)??hongKongDate().slice(0,7),prior=previousCalendarMonth(month);const ids=(m:string)=>new Set(row?.records.filter(i=>i.kind==='stock'&&i.date.startsWith(m)).map(i=>i.id));const currentIds=ids(month),priorIds=ids(prior??'');const moves=data.data?priceMoves(itemRanking(data.data.lines.filter(l=>currentIds.has(l.invoice_id)),data.data.lines.filter(l=>priorIds.has(l.invoice_id)),data.data.products)):[];
 async function save(){if(!row||!data.tenantId)return;setBusy(true);const {error}=await supabase.from('suppliers').update({...form,delivery_days:form.delivery_days.split(',').map(s=>s.trim()).filter(Boolean)}).eq('id',row.id).eq('tenant_id',data.tenantId);setBusy(false);if(error){toast.error(error.message);return;}await data.refetch();setEditing(false);toast.success('Supplier profile saved');}
 return <Dialog open onOpenChange={o=>!o&&onClose()}><DialogContent className="!bg-card !backdrop-blur-none max-w-2xl max-h-[85svh] overflow-y-auto overflow-x-hidden"><DialogHeader><DialogTitle>{row?.name??'Supplier profile'}</DialogTitle><DialogDescription>{data.isPending?'Loading profile…':`${payables.loading?'Checking owed amounts…':formatCurrency(owed)+' owed'} · ${row?.records.length??0} invoices`}</DialogDescription></DialogHeader>{data.isError&&<p className="text-destructive">Could not load supplier profile.</p>}{row&&<><div className="grid grid-cols-1 sm:grid-cols-2 gap-4">{(Object.keys(form) as (keyof typeof form)[]).map(key=><div key={key} className={key==='notes'||key==='address'?'sm:col-span-2':''}><Label htmlFor={`supplier-${key}`}>{({contact_person:'Contact',email:'Email',phone:'Phone',address:'Address',payment_terms:'Payment terms',delivery_days:'Delivery days',notes:'Notes'})[key]}</Label>{editing?(key==='notes'||key==='address'?<Textarea id={`supplier-${key}`} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/>:<Input id={`supplier-${key}`} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/>):<p className="text-sm break-words whitespace-pre-wrap mt-1">{form[key]||'Not recorded'}</p>}</div>)}</div><div className="flex flex-wrap gap-2">{isAdmin&&!isPreviewActive&&(editing?<><Button disabled={busy} onClick={save}>Save</Button><Button variant="outline" onClick={()=>setEditing(false)}>Cancel</Button></>:<Button variant="outline" onClick={()=>setEditing(true)}>Edit profile</Button>)}<Button asChild variant="outline"><Link to={`/procurement/finance/suppliers/${row.id}`}>Supplier Accounts · full ledger</Link></Button></div><h3 className="font-semibold">Recent invoices · stock &amp; expense</h3><div className="divide-y divide-border">{row.records.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(i=><div key={`${i.kind}-${i.id}`} className="py-2 text-sm flex justify-between gap-3"><div className="min-w-0"><Link className="underline break-words" to={i.kind==='stock'?`/procurement/invoices?invoice=${i.id}`:'/expenses'}>{i.number||'Bill'} · {i.kind==='stock'?'Invoice':'Expense'}</Link><p className="text-muted-foreground text-xs">{formatDate(i.date)}</p></div><span className="td-num shrink-0">{formatCurrency(i.total)}</span></div>)}</div><h3 className="font-semibold">Price changes · same unit</h3>{moves.slice(0,6).map(m=><p key={m.id} className={`text-sm break-words ${(m.priceChange??0)>0?'text-warning':'text-success'}`}>{m.name} · {formatMenuCurrency(m.previousPrice??0)} → {formatMenuCurrency(m.price??0)} per {m.unit} · {formatPercent(m.priceChange)}</p>)}{!moves.length&&<p className="text-sm text-muted-foreground">No comparable price moves over 5%.</p>}</>}</DialogContent></Dialog>;
}